lab.solution:
parent = {'ana': 'ana', 'ben': 'ben', 'cam': 'cam'}

def find(item):
    while parent[item] != item:
        item = parent[item]
    return item

def union(left, right):
    left_root, right_root = find(left), find(right)
    if left_root != right_root:
        parent[right_root] = left_root

union('ana', 'ben')
assert find('ana') == find('ben')
assert find('ana') != find('cam')
union('ben', 'cam')
assert find('ana') == find('cam')
